css:
.btn-wrapper {
  --font-size: 17px;
  --font-weight: 600;
  --primary-color: #fff;
  --secondary-color: #000;
  --border-radius: 1em;
  --highlight-color-hue: 200;
  --hue-1: 190;
  --hue-2: 210;
  --bg-radial-color: hsl(var(--hue-1), 100%, 70%);
  --bg-linear-color: hsl(var(--hue-2), 90%, 70%);
  --highlight-color: hsl(var(--highlight-color-hue), 100%, 70%);
  --highlight-color-2: hsl(var(--highlight-color-hue), 90%, 80%);
}

.btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.7rem 1.6rem;
  font-size: var(--font-size);
  font-weight: var(--font-weight);
  color: var(--primary-color);
  background: radial-gradient(
      120% 150% at 0% 50%,
      transparent 40%,
      var(--bg-radial-color) 100%
    ),
    linear-gradient(
      180deg,
      hsl(var(--hue-1), 80%, 75%) 0%,
      var(--bg-linear-color) 100%
    );
  background-blend-mode: overlay, normal;
  border: 1px solid hsl(var(--hue-1), 90%, 70%);
  border-radius: var(--border-radius);
  outline: none;
  cursor: pointer;
  box-shadow:
    0 0 0 0 #0000,
    inset 0 -0.15em 0 0 hsl(var(--hue-1), 100%, 70%),
    inset 0 0.1em 0 0 hsl(var(--hue-1), 100%, 85%),
    0 0 3px 0 hsl(var(--hue-1), 90%, 60%),
    0 0 6px 0 #0009;
  text-shadow: 0 -1px 1px hsl(var(--hue-1), 80%, 80%);
  transition:
    filter 0.3s ease,
    background-color 0.3s ease;
  overflow: hidden;
}

.btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(
    50% 50% at 50% 0%,
    var(--highlight-color-2) 0%,
    transparent 50%
  );
  mix-blend-mode: overlay;
  pointer-events: none;
  opacity: 0.9;
}

.btn::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: var(--border-radius);
  box-shadow:
    inset 0 0 12px 0 var(--highlight-color),
    inset 0 0 18px 0 var(--highlight-color-2);
  pointer-events: none;
  transition:
    box-shadow 0.3s ease,
    opacity 0.3s ease;
  opacity: 0.8;
}

.btn-svg {
  width: 1.3em;
  height: 1.3em;
  fill: hsl(var(--hue-1), 90%, 80%);
  filter: drop-shadow(0 0 6px hsl(var(--highlight-color-hue), 90%, 60%));
  animation: sparkle 1.8s ease-in-out infinite;
  z-index: 1;
}

.btn:active {
  background: hsl(var(--hue-2), 80%, 55%);
  box-shadow:
    inset 0 -0.15em 0 0 hsl(var(--hue-1), 100%, 65%),
    inset 0 0.15em 0 0 hsl(var(--hue-1), 100%, 85%),
    0 0 0 0 transparent,
    0 0 6px 0 var(--highlight-color),
    0 0 12px 0 #000a;
  filter: saturate(1.4);
  transform: scale(0.95);
}

.btn:active .btn-svg {
  transform: scale(1.1);
  fill: #fff;
  animation: none;
}

.txt-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  overflow: hidden;
  position: relative;
  height: 1.2em;
  z-index: 1;
}

.txt-1,
.txt-2 {
  display: flex;
  gap: 0.05em;
}

.txt-1 {
  display: flex;
  transform: translateY(-100%);
  opacity: 0;
  transition: transform 0.5s ease;
}

.txt-2 {
  display: flex;
  transform: translateY(0);
  transition: transform 0.5s ease;
}

.btn-letter {
  display: inline-block;
}

.btn:hover .txt-1 {
  transform: translateY(0);
  opacity: 1;
}

.btn:hover .txt-2 {
  transform: translateY(100%);
}

@keyframes sparkle {
  0%,
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }

  50% {
    transform: scale(1.1) rotate(-5deg);
    opacity: 0.85;
  }
}

.btn:hover {
  filter: brightness(1.1);
  background: linear-gradient(
    180deg,
    hsl(var(--hue-1), 100%, 80%) 0%,
    var(--bg-linear-color) 100%
  );
  background-blend-mode: overlay, normal;
}

.btn:hover::after {
  box-shadow:
    inset 0 0 14px 0 var(--highlight-color),
    inset 0 0 20px 0 var(--highlight-color-2);
  opacity: 1;
}

.btn:hover .btn-svg {
  fill: #fff;
  filter: drop-shadow(0 0 3px hsl(var(--highlight-color-hue), 100%, 70%))
    drop-shadow(0 -4px 6px #0009);
  animation: none;
}
